import React, { useState, useEffect } from 'react';
import { getStore3AllSales, createStore3Sale } from '../../services/store3Service';

const SalesOperations = () => {
    const [stocks, setStocks] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    const [saleForm, setSaleForm] = useState({
        productId: '',
        quantity: 0,
        customerName: '',
        customerPhone: '',
        paymentMethod: ''
    });

    useEffect(() => {
        fetchStocks();
    }, []);

    const fetchStocks = async () => {
        try {
            setLoading(true);
            const response = await getStore3AllSales();
            if (response.success) {
                setStocks(response.stocks);
            } else {
                setError(response.message);
            }
        } catch (err) {
            setError('Stok verileri yüklenirken bir hata oluştu');
        } finally {
            setLoading(false);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const selectedStock = stocks.find(stock => stock.id === saleForm.productId);
            if (!selectedStock) {
                setError('Lütfen bir ürün seçin');
                return;
            }

            if (saleForm.quantity > selectedStock.quantity) {
                setError('Seçilen miktar stok miktarından fazla olamaz');
                return;
            }

            const response = await createStore3Sale({
                ...saleForm,
                totalPrice: selectedStock.unitPrice * saleForm.quantity
            });

            if (response.success) {
                alert('Satış başarıyla oluşturuldu');
                fetchStocks();
                setSaleForm({
                    productId: '',
                    quantity: 0,
                    customerName: '',
                    customerPhone: '',
                    paymentMethod: ''
                });
            } else {
                setError(response.message);
            }
        } catch (err) {
            setError('Satış oluşturulurken bir hata oluştu');
        }
    };

    if (loading) {
        return (
            <div className="flex justify-center items-center h-screen">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
            </div>
        );
    }

    return (
        <div className="p-6">
            <h1 className="text-3xl font-bold mb-8">Store 3 - Satış İşlemleri</h1>

            {/* Satış Oluşturma Formu */}
            <div className="bg-white rounded-lg shadow-md p-6 mb-8">
                <h2 className="text-xl font-bold mb-4">Yeni Satış Oluştur</h2>
                {error && (
                    <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-4">
                        {error}
                    </div>
                )}
                <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <select
                        className="border p-2 rounded"
                        value={saleForm.productId}
                        onChange={(e) => setSaleForm({...saleForm, productId: e.target.value})}
                        required
                    >
                        <option value="">Ürün Seçin</option>
                        {stocks.map(stock => (
                            <option key={stock.id} value={stock.id}>
                                {stock.productName} - {stock.productCode} ({stock.quantity} adet)
                            </option>
                        ))}
                    </select>
                    <input
                        type="number"
                        placeholder="Miktar"
                        className="border p-2 rounded"
                        value={saleForm.quantity}
                        onChange={(e) => setSaleForm({...saleForm, quantity: parseInt(e.target.value)})}
                        required
                        min="1"
                    />
                    <input
                        type="text"
                        placeholder="Müşteri Adı"
                        className="border p-2 rounded"
                        value={saleForm.customerName}
                        onChange={(e) => setSaleForm({...saleForm, customerName: e.target.value})}
                        required
                    />
                    <input
                        type="text"
                        placeholder="Müşteri Telefonu"
                        className="border p-2 rounded"
                        value={saleForm.customerPhone}
                        onChange={(e) => setSaleForm({...saleForm, customerPhone: e.target.value})}
                        required
                    />
                    <select
                        className="border p-2 rounded"
                        value={saleForm.paymentMethod}
                        onChange={(e) => setSaleForm({...saleForm, paymentMethod: e.target.value})}
                        required
                    >
                        <option value="">Ödeme Yöntemi Seçin</option>
                        <option value="Nakit">Nakit</option>
                        <option value="Kredi Kartı">Kredi Kartı</option>
                        <option value="Havale">Havale</option>
                    </select>
                    <button type="submit" className="bg-green-500 text-white p-2 rounded hover:bg-green-600 md:col-span-2">
                        Satış Oluştur
                    </button>
                </form>
            </div>

            {/* Mevcut Stok Tablosu */}
            <div className="bg-white rounded-lg shadow-md p-6">
                <h2 className="text-xl font-bold mb-4">Mevcut Stok Durumu</h2>
                <div className="overflow-x-auto">
                    <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50">
                            <tr>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Ürün Kodu
                                </th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Ürün Adı
                                </th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Kategori
                                </th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Stok Miktarı
                                </th>
                                <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                                    Birim Fiyat
                                </th>
                            </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                            {stocks.map((stock) => (
                                <tr key={stock.id}>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                        {stock.productCode}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                        {stock.productName}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                        {stock.category}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                        {stock.quantity}
                                    </td>
                                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                                        {new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' })
                                            .format(stock.unitPrice)}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default SalesOperations;
